def transform(grid):
    from collections import deque

    h, w = len(grid), len(grid[0])

    # The small cross marks (and their occasional single coloured centre cells)
    # are annotations.  Remove them by flood-filling from the substantial colour
    # regions, then transpose the cleaned picture.
    large = [[False] * w for _ in range(h)]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if seen[r][c] or grid[r][c] == 1:
                continue
            colour = grid[r][c]
            q = [(r, c)]
            seen[r][c] = True
            cells = []
            for x, y in q:
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and not seen[nx][ny] and grid[nx][ny] == colour:
                        seen[nx][ny] = True
                        q.append((nx, ny))
            if len(cells) >= 8:
                for x, y in cells:
                    large[x][y] = True

    clean = [[grid[r][c] if large[r][c] else -1 for c in range(w)] for r in range(h)]
    q = deque((r, c) for r in range(h) for c in range(w) if clean[r][c] >= 0)
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and clean[nr][nc] < 0:
                clean[nr][nc] = clean[r][c]
                q.append((nr, nc))

    out = [list(row) for row in zip(*clean)]
    recolour = {3: 8, 7: 3, 0: 7, 2: 0, 6: 2, 8: 6, 4: 4, 9: 0}
    return [[recolour.get(v, v) for v in row] for row in out]
